*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearchInit();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if (!await scwin.fnDisclosureAllSetting()) {
        return;
    }
    if (($c.util.getComponent('ipt_reportNmTmp').getValue() == null ? '' : String($c.util.getComponent('ipt_reportNmTmp').getValue())) === '') {
        $c.util.getComponent('ipt_reportCd').setValue("");
    }
    if (($c.util.getComponent('ipt_reportCd').getValue() == null ? '' : String($c.util.getComponent('ipt_reportCd').getValue())) !== '') {
        (($c.util.getComponent('ipt_reportNmTmp')) && ($c.util.getComponent('ipt_reportNmTmp')).setDisabled ? ($c.util.getComponent('ipt_reportNmTmp')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    }
    if ($("#searchForm").find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $("#searchForm").find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchMarketAlertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "marketAlertList_sub");
    document.searchForm.ajaxSubmit({ ajaxUrl: '/disclosure/marketalertlist.do', ajaxCallBack: scwin.fnSearchCallBack });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if (($c.util.getComponent('ipt_reportNmTmp').getValue() == null ? '' : String($c.util.getComponent('ipt_reportNmTmp').getValue())) === '') {
        $c.util.getComponent('ipt_reportCd').setValue("");
    } else {
        (($c.util.getComponent('ipt_reportNmTmp')) && ($c.util.getComponent('ipt_reportNmTmp')).setDisabled ? ($c.util.getComponent('ipt_reportNmTmp')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchMarketAlertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "marketAlertList_down");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCheckAllDscls
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnCheckAllDscls = function () {
    /* sdd-asis-lifecycle:begin fnCheckAllDscls — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isCheck = false;
    const allChk = $("#searchForm").find("input:checkbox[name=ipt_dsclsLayerAll]");
    if (allChk.attr("checked") === "checked") {
        isCheck = true;
    }
    $("#searchForm").find("input:checkbox[name=disclosureTypeArr]").each(function() {
            if (isCheck) {
                $(this).attr("checked", "checked");
            } else {
                $(this).removeAttr("checked");
            }
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDisclosureAllSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDisclosureAllSetting = async function () {
    /* sdd-asis-lifecycle:begin fnDisclosureAllSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let varCheckSetting = "";
    const setName = $("#searchForm > #disclsTpArr");
    $("#searchForm").find("input:checkbox[name=disclosureTypeArr]").each(function() {
            if ($(this).attr("checked") === "checked") {
                varCheckSetting += $(this).val();
            }
    });
    if (varCheckSetting === "") {
        await $c.win.alert("Please check 'Disclosure Type' at least one.");
        return false;
    } else {
        setName.val(varCheckSetting);
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
